/*************** CK 에디터4*******************/

/*
 * 쉘에서 init 이벤트 발생 시 호출.
 */
function onShlCkEditorInit(e){
	var sampleThr2 = e.control;
	//최초 init 이벤트에서 e.content는 null입니다. 2번째 이벤트부터 DOM을 갖고 있습니다.
	if(e.content){//DOM에 이미 그려져 있으면 load 이벤트 호출 방지
		e.preventDefault(); //다음에 일어나는 쉘 load이벤트 발생을 방지합니다.
	}
}

/*
 * 쉘에서 load 이벤트 발생 시 호출.
 */
function onShlCkEditorLoad(e) {
	var shlCkEditor = e.control;
	var content = e.content;
	
	loadCkEditor(content);	
}

function loadCkEditor(content) {
	var shlCkEditor = app.lookup("sampleThr");
	shlCkEditor.registerComponent("ckeditor", content);
	
	var elckEditor = document.createElement("ckeditor");
	elckEditor.id = "sampleCkeditor";
	content.appendChild(elckEditor);
	
	var objEditor = CKEDITOR.replace(elckEditor, {
		width: 'auto',
		height: 300,
		allowedContent: true,
		//글자수 제한 없음
		wordcount: [{
			showCharCount: true
		}, {
			maxCharCount: -1
		}],
		startupFocus: true,
		on: {
			instanceReady: function(evt) {
				evt.editor.setReadOnly(false);
			}
		}
	});
	
	CKEDITOR.instances.sampleCkeditor.setData('<p><span style="background-color:rgb(255,255,255);color:rgb(0,117,200);font-size:36px;">'
		+ '<strong>eXBuilder6&nbsp;</strong></span><span style="color:rgb(0,0,0);font-size:36px;">웹 에디터 연동</span></p><p>&nbsp;</p>'
  		+ '<table border="1" cellpadding="1" cellspacing="1" style="width: 500px;"><tbody><tr><td style="background-color: rgb(156, 156, 156);">&nbsp;</td><td style="background-color: rgb(156, 156, 156);">&nbsp;</td><td style="background-color: rgb(156, 156, 156);">&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table><p><br></p>'
	);
}

/*
 * 임베디드 페이지에서 load 이벤트 발생 시 호출.
 * 페이지의 Load가 완료되었을 때 호출되는 Event.
 */
function onEmpEditorLoad(e){
	var empEditor = e.control;
	
	cpr.core.DeferredUpdateManager.INSTANCE.asyncExec(function(){
		setTimeout(function(){
			app.lookup("empEditor").callPageMethod("pasteHTML", msEditorSmpVal);
		}, 500)		
	});
}


